function setStudioSpeed(n){if(studioRuntime)studioRuntime.speed=Number(n)}
function studioReplay(play=true){if(!studioRuntime)return;studioPause();studioRuntime.time=0;studioDraw();if(play)studioStart()}
function studioStepFrame(){if(!studioRuntime)return;if(studioTab==='movement'&&!movementSafety){toast('Please acknowledge the movement safety guidance first.');return}studioPause();let r=studioRuntime;if(studioTab==='movement'){let dur=movements[movementId].duration;r.time=(Math.floor(r.time/(dur/4))+1)*(dur/4);if(r.time>=dur*movementCycles)r.time=0}else if(studioTab==='sbar'){r.time=(Math.floor(r.time/3)+1)*3;if(r.time>15)r.time=0}else r.time=(r.time+2)%8;studioDraw()}
function hygieneSide(){if(hygieneIndex>=6){let right=hygieneAnswers.filter(Boolean).length;return `<span class="eyebrow">YOUR LEARNING DEBRIEF</span><div class="studio-result"><div class="result-number">${right}<span style="font-size:var(--t-18);letter-spacing:0"> / 6</span></div><h3>Moments recognized on the first try</h3><p>A practice result, not a competency score.</p></div>${hygieneScenes.map((s,i)=>`<div class="studio-review-row"><span>${s.title}</span><span>${hygieneAnswers[i]?'✓ Recognized':'↺ Reviewed'}</span></div>`).join('')}<div class="studio-callout">The key is the indication, not a rigid number of cleaning actions. Follow local hand-hygiene method and infection-control requirements.</div><div class="studio-next"><button class="btn secondary" data-action="engine-6" data-engine-6="[]">Try again ↺</button><button class="btn" data-action="engine-7" data-engine-7="${esc(JSON.stringify([right]))}">Save reflection ✓</button></div>`}let s=hygieneScenes[hygieneIndex],answered=hygieneSelected!==null;return `<div style="display:flex;justify-content:space-between;align-items:center"><span class="eyebrow">WATCH → DECIDE → REFLECT</span><div class="studio-steps-progress">${hygieneScenes.map((_,i)=>`<span class="${i<hygieneIndex?'done':i===hygieneIndex?'active':''}"></span>`).join('')}</div></div><h3>${s.title}</h3><p>${s.context}</p><p style="margin-top:12px;font-size:var(--t-12);font-weight:700;color:var(--ink)">Which indication best fits this pause?</p><div class="studio-options">${hygieneMoments.map((m,i)=>`<button class="studio-choice ${answered&&i===s.correct?'good':''} ${answered&&i===hygieneSelected&&i!==s.correct?'wrong':''}" ${answered?'disabled':''} data-action="engine-8" data-engine-8="${esc(JSON.stringify([i]))}"><span class="number">${i===5?'—':i+1}</span><span>${m}</span></button>`).join('')}</div><div aria-live="polite">${answered?`<div class="studio-feedback ${hygieneSelected===s.correct?'correct':''}"><strong>${hygieneSelected===s.correct?'A well-placed pause.':'Let’s look at the indication.'}</strong>${s.feedback}</div>`:''}</div><div class="studio-next"><small class="muted" style="font-size:var(--t-12)">No time pressure. Reason it through.</small><button class="btn small" ${!answered?'disabled':''} data-action="engine-9" data-engine-9="[]">${hygieneIndex===5?'See debrief':'Next scene'} →</button></div><div class="studio-callout">The room is illustrative. Highlights are teaching markers, not detected contamination. Read the vignette for the full context.</div>`}
function answerHygiene(i){if(hygieneSelected!==null||hygieneIndex>=6)return;hygieneSelected=i;hygieneAnswers.push(i===hygieneScenes[hygieneIndex].correct);$('#hygieneSide').innerHTML=hygieneSide();if(studioRuntime){studioRuntime.time=0;studioDraw()}}
function nextHygiene(){if(hygieneSelected===null)return;hygieneIndex++;hygieneSelected=null;hotspotSelected=-1;renderStudioWorkbench()}
function renderStudioWorkbench(){studioDispose();$('#studioWorkbench').innerHTML=studioWorkbench();studioInit()}
function studioDispose(){if(studioRuntime){cancelAnimationFrame(studioRuntime.raf);studioRuntime.observer?.disconnect();studioRuntime=null}}
function studioInit(){const canvas=$('#studioCanvas');if(!canvas)return;studioRuntime={canvas,ctx:canvas.getContext('2d'),time:0,speed:1,playing:false,raf:0,last:0,phase:-1};studioRuntime.observer=new ResizeObserver(()=>{if(studioRuntime&&studioRuntime.canvas===canvas)studioDraw()});studioRuntime.observer.observe(canvas);studioDraw();studioUpdatePlayback()}
function resetHygiene(){hygieneIndex=0;hygieneSelected=null;hygieneAnswers=[];hotspotSelected=-1;renderStudioWorkbench()}
function exploreHotspot(i){hotspotSelected=i;document.querySelectorAll('.studio-hotspot').forEach((b,j)=>b.setAttribute('aria-pressed',j===i));let labels=['Patient contact','Clean-task area','Exposure-risk task','Patient surroundings','Hand-hygiene station'],notes=['Before and after patient contact are distinct indications. Read the vignette to know which applies.','A clean or aseptic task creates its own before-task indication. This is not a technique demonstration.','Following body-fluid exposure risk, hand hygiene is required, including after glove removal.','Bedside surfaces can matter even when you do not touch the patient.','Use the appropriate method. Soap and water are needed when visibly soiled; follow local and organism-specific guidance.'];$('#studioCaption').innerHTML=`<strong>${labels[i]}</strong>${notes[i]}`;studioDraw()}
function sbarWorkbench(){return `<header class="studio-workbench-top"><div><h2>Pass the message clearly</h2><p>Build a fictional SBAR handover, then close the loop.</p></div><span class="pill skills">Drag, tap, or use a keyboard</span></header><div class="studio-workbench-body"><div class="studio-visual">${studioCanvas('Two illustrative healthcare practitioners. An animated message passes from sender to receiver through the Situation, Background, Assessment, and Recommendation stages, then an acknowledgment returns.','<strong>A handover is more than a message.</strong>Make the concern, request, and ownership clear.', '<span class="studio-scene-step">SBAR + CLOSED LOOP</span>')}${studioPlayback('sbar')}<div style="padding:0 18px 16px;font-size:var(--t-12);color:var(--muted);background:var(--surface)">Watch the example, then practise matching the four message cards.</div></div><div class="studio-side" id="sbarSide">${sbarSide()}</div></div>${studioFoot('sbar','Fictional communication practice. Do not delay urgent escalation to complete a script.')}`}
function sbarSide(){let correct=sbarChecked&&sbarSlots.every((v,i)=>v===i);return `<div class="studio-sbar-body"><div class="studio-sbar-context"><span class="eyebrow">A FICTIONAL HANDOVER</span><h3>Put clarity in the right order.</h3><p>Drag each message into its matching SBAR slot. Or select a message, then select a slot. A filled slot can be cleared.</p></div><div><div class="sbar-slots">${sbarParts.map((p,i)=>`<button class="sbar-slot ${sbarSlots[i]!==null?'filled':''} ${sbarChecked?(sbarSlots[i]===i?'match':'mismatch'):''}" aria-label="${p.name} slot${sbarSlots[i]!==null?', filled. Activate to remove.':', empty. Select a message then activate.'}" data-action="engine-10" data-engine-10="${esc(JSON.stringify([i]))}" data-ondragover="engine-11" data-engine-11="[]" data-ondragleave="engine-12" data-engine-12="[]" data-ondrop="engine-13" data-engine-13="${esc(JSON.stringify([i]))}"><span class="slot-letter">${p.key}</span><span class="slot-content">${sbarSlots[i]===null?`<b>${p.name}</b><br>Select or drop a message here`:sbarParts[sbarSlots[i]].text}</span>${sbarSlots[i]!==null?'<span class="slot-clear" aria-hidden="true">×</span>':''}</button>`).join('')}</div></div><div>${[3,1,0,2].some(i=>!sbarSlots.includes(i))?'<span class="eyebrow">MESSAGE CARDS</span>':''}<div class="sbar-pool">${[3,1,0,2].filter(i=>!sbarSlots.includes(i)).map(i=>`<button class="sbar-card ${sbarSelected===i?'selected':''}" draggable="true" data-ondragstart="engine-14" data-engine-14="${esc(JSON.stringify([i,i]))}" data-action="engine-15" data-engine-15="${esc(JSON.stringify([i]))}" aria-pressed="${sbarSelected===i}"><span class="handle" aria-hidden="true">⠿</span><span>${sbarParts[i].text}</span></button>`).join('')}</div><div class="studio-screenreader" role="status" id="sbarSelectionStatus">${sbarSelected!==null?'Message selected. Choose a slot.':''}</div></div></div><div id="sbarFeedback" aria-live="polite">${sbarChecked?`<div class="studio-feedback ${correct?'correct':''}"><strong>${correct?(sbarGuided?'Guided example arranged.':'A clear structure.'):'Some messages need another place.'}</strong>${correct?'Situation leads with the concern. Background gives relevant context. Assessment states your findings and concern. Recommendation asks for an action.':'Match the current concern to Situation, prior context to Background, your interpretation to Assessment, and your request to Recommendation. Clear and move the highlighted cards.'}</div>`:''}</div>${correct?`<h3 style="font-size:var(--t-14)">One more step: close the loop.</h3><p style="font-size:var(--t-12)">The recipient has heard the message. What must be confirmed?</p><div class="studio-options" style="grid-template-columns:1fr"><button class="studio-choice" data-action="engine-16" data-engine-16="[]">That the message sounded confident.</button><button class="studio-choice" data-action="engine-17" data-engine-17="[]">Who will act, when, and how to escalate if the plan is not carried out.</button></div><div id="sbarAck" aria-live="polite">${sbarAcknowledged?'<div class="studio-feedback correct"><strong>The loop is closed.</strong>Shared understanding includes an owner, timing, and a contingency plan.</div>':''}</div>${sbarAcknowledged?'<button class="btn" data-action="engine-18" data-engine-18="[]">Save learning reflection ✓</button>':''}`:`<div class="studio-next"><button class="text-link" data-action="engine-19" data-engine-19="[]">Show an example</button><button class="btn small" ${sbarSlots.includes(null)?'disabled':''} data-action="engine-20" data-engine-20="[]">Check my handover →</button></div>`}<div class="studio-next"><button class="text-link" data-action="engine-21" data-engine-21="[]">Start again ↺</button><small class="muted" style="font-size:var(--t-12)">Not a clinical performance assessment</small></div>`}
function chooseSbar(i){sbarSelected=i;sbarChecked=false;sbarAcknowledged=false;$('#sbarSide').innerHTML=sbarSide();document.querySelector('.sbar-slot:not(.filled)')?.focus()}
function placeSbar(slot){if(sbarSelected!==null&&!sbarSlots.includes(sbarSelected)){sbarSlots[slot]=sbarSelected;sbarSelected=null}else if(sbarSlots[slot]!==null){sbarSlots[slot]=null}sbarChecked=false;sbarAcknowledged=false;$('#sbarSide').innerHTML=sbarSide()}
function dropSbar(e,slot){e.preventDefault();let raw=e.dataTransfer.getData('text/plain');if(!/^carecraft-sbar:[0-3]$/.test(raw))return;let n=Number(raw.split(':')[1]);if(sbarSlots.includes(n))return;sbarSelected=n;placeSbar(slot)}
function checkSbar(){if(sbarSlots.includes(null))return;sbarChecked=true;$('#sbarSide').innerHTML=sbarSide();if(sbarSlots.every((v,i)=>v===i)){studioReplay(false);if(!studioReducedMotion())studioStart()}}
function showSbarExample(){sbarSlots=[0,1,2,3];sbarSelected=null;sbarChecked=true;sbarGuided=true;sbarAcknowledged=false;$('#sbarSide').innerHTML=sbarSide();studioReplay(false);if(!studioReducedMotion())studioStart()}
function resetSbar(){sbarSlots=[null,null,null,null];sbarSelected=null;sbarChecked=false;sbarGuided=false;sbarAcknowledged=false;$('#sbarSide').innerHTML=sbarSide();studioReplay(false)}
function acknowledgeSbar(good){if(good){sbarAcknowledged=true;$('#sbarSide').innerHTML=sbarSide();if(studioRuntime){studioRuntime.time=13;studioDraw();if(!studioReducedMotion())studioStart()}}else $('#sbarAck').innerHTML='<div class="studio-feedback"><strong>Confidence alone does not close the loop.</strong>Confirm action, ownership, timing, and the contingency plan.</div>'}
function saveSbarStudio(){logStudio('sbar','SBAR + closed loop',sbarGuided?'Guided example and closed-loop reflection reviewed':'All SBAR parts matched; closed-loop action identified')}
function movementWorkbench(){let m=movements[movementId];return `<header class="studio-workbench-top"><div><h2>A little space to move</h2><p>Watch a simplified demonstration. No movement is measured.</p></div><span class="pill attitudes">Practitioner wellbeing</span></header><div class="studio-workbench-body"><div class="studio-visual"><div class="studio-movement-selector" role="group" aria-label="Select movement">${Object.entries(movements).map(([id,x])=>`<button class="${id===movementId?'active':''}" aria-pressed="${id===movementId}" data-action="engine-22" data-engine-22="${esc(JSON.stringify([id]))}">${x.short}</button>`).join('')}</div>${studioCanvas('An original seated mannequin illustrates '+m.title+'. The numbered text instructions describe the movement.','<strong id="movementCue">'+m.phases[0]+'</strong><span id="movementCueNote">Playback pace is illustrative. Use your own comfortable range.</span>',`<span class="studio-scene-step">${movementId==='chest'?'FRONT VIEW':'SIDE VIEW'} · ILLUSTRATIVE</span><div class="studio-cycle-ring" id="movementRing"><span id="movementLoop">0 / ${movementCycles}<br><span style="font-size:var(--t-12)">LOOPS</span></span></div>`)}${studioPlayback('movement')}<div class="studio-scrubber"><span>Scrub</span><input id="movementScrub" type="range" min="0" max="100" value="0" aria-label="Move through the illustration" data-oninput="engine-23" data-engine-23="[]"><span id="movementPercent">0%</span></div><div class="studio-controls" style="padding-top:0;border:0"><label for="movementCycleSelect">Preview loops <select id="movementCycleSelect" data-onchange="engine-24" data-engine-24="[]">${[1,3,5].map(n=>`<option value="${n}" ${n===movementCycles?'selected':''}>${n}</option>`).join('')}</select></label><span style="font-size:var(--t-12);color:var(--muted)">Counts animation loops, not your repetitions.</span></div></div><div class="studio-side"><span class="eyebrow">A SMALL BREAK, AT YOUR OWN PACE</span><h3>${m.title}</h3><p>${m.description}</p><div class="studio-safety-band" style="font-size:var(--t-12);margin:13px 0">Use a stable chair without wheels. Only take a break when safely away from active care duties. Stop if you feel pain, dizziness, or unusual breathlessness. If unsure about suitability, seek advice from a qualified health professional.</div><label style="display:flex;gap:9px;font-size:var(--t-12);line-height:1.7;align-items:flex-start;margin:13px 0;color:var(--muted)"><input id="movementSafety" type="checkbox" style="accent-color:#356e4a;margin-top:4px" ${movementSafety?'checked':''} data-onchange="engine-25" data-engine-25="[]">I have read the safety guidance. I understand this is a general demonstration, not a personalized exercise prescription.</label><div>${m.steps.map((text,i)=>`<div class="movement-step ${i===0?'active':''}" data-movement-step="${i}"><span class="number">${i+1}</span><p>${text}</p></div>`).join('')}</div><div class="studio-callout">${m.sourceNote} No camera, posture analysis, or physical-performance score is used.</div><div class="studio-next"><button class="text-link" data-action="engine-26" data-engine-26="[]">Safety & suitability</button><button class="btn small" data-action="engine-27" data-engine-27="[]">Reflect on this break ↗</button></div><div id="movementStatus" role="status" style="font-size:var(--t-12);color:var(--muted);margin-top:12px">${studioReducedMotion()?'Reduced-motion preference detected: use Step or the scrubber. Play is available if you choose.':'Playback starts only when you choose.'}</div></div></div>${studioFoot('nhs','General movement cues adapted from NHS sitting exercises. Animation range and tempo are not treatment targets.')}`}
function selectMovement(id){studioPause();movementId=id;renderStudioWorkbench()}
function setMovementSafety(yes){movementSafety=yes;if(!yes)studioPause()}
function setMovementCycles(n){movementCycles=Number(n);studioReplay(false)}
function scrubMovement(v){if(!movementSafety){$('#movementScrub').value=0;toast('Please read and acknowledge the movement safety guidance first.');return}studioPause();if(studioRuntime){studioRuntime.time=movements[movementId].duration*Number(v)/100;studioDraw()}}
function openMovementSafety(){showModal('Move within your own limits.','General demonstrations, not individualized rehabilitation.',`<p>The seated examples are adapted from NHS sitting-exercise guidance. The figures simplify movement and cannot establish the range, speed, or repetition count appropriate for you.</p><div class="takeaway"><p>Use a solid, stable chair without wheels, with your feet supported at the start. Give yourself enough space. Move gently and breathe normally. Do not follow the animation into an uncomfortable range.</p></div><p>If you have an injury, recent surgery, restrictions, significant symptoms, or are uncertain about suitability, ask a qualified health professional before trying the movement. Stop for pain, dizziness, or unusual breathlessness. Seek urgent help for severe or concerning symptoms.</p><h3>What this app can—and cannot—do</h3><p>It can show a simplified movement, pause, slow down, and count its own illustration loops. It cannot see you, confirm safe technique, prescribe treatment, or verify that you performed an exercise.</p><div class="modal-actions"><button class="btn" data-action="engine-28" data-engine-28="[]">Return to the studio</button></div>`)}
function logMovementReflection(){showModal('A moment to notice.','Optional, self-reported reflection.',`<p>You do not have to perform a movement to learn from its demonstration. What did you choose?</p><div class="form-group"><label for="movementReflectionType">My activity</label><select id="movementReflectionType"><option>I reviewed the demonstration only</option><option>I took a comfortable movement break</option><option>I chose not to move and will seek advice if needed</option></select></div><div class="form-group"><label for="movementReflectionText">One thing I noticed (optional)</label><textarea id="movementReflectionText" maxlength="700" placeholder="A brief, non-confidential reflection…"></textarea><small>Stored in this browser. Avoid personal health details or information about others.</small></div><div class="modal-actions"><button class="btn" data-action="engine-29" data-engine-29="[]">Save my reflection ✓</button></div>`)}
function saveMovementReflection(){let type=$('#movementReflectionType').value,note=$('#movementReflectionText').value;logStudio('movement-'+movementId,movements[movementId].short,type+(note?' — '+note:''));closeModal()}
function studioLogHtml(){let records=studioRecords();return records.length?`<div class="studio-mini-log">${records.map(r=>`<span>✓ ${esc(r.label)}</span>`).join('')}</div>`:'<p>No studio activity recorded yet. Start with one exercise.</p>'}
function studioRecords(){return Array.isArray(state.studioRecords)?state.studioRecords:[]}
function hcaConfigureQuestion(id,index=0){hcaQuestionIndex=Math.max(0,Math.min(2,index));const q=HCA_BANK[id][hcaQuestionIndex],l=lessons.find(x=>x.id===id);const map=hcaAnswerMaps[q.id]||(hcaAnswerMaps[q.id]=hcaShuffle(q.answers.length));Object.assign(l,{question:q.question,answers:map.map(i=>q.answers[i]),correct:map.indexOf(q.correct),rationales:map.map(i=>q.rationales[i]),feedback:q.rationales[q.correct]});}
function hcaShuffle(n){const a=Array.from({length:n},(_,i)=>i);for(let i=n-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function ccOpenStudio(id){const s=CC_STUDIOS.find(x=>x.id===id);if(!s)return;ccCurrentGuide=id;ccStudio={id,index:0,selected:null,history:[],order:[],checked:false,classified:[],baseline:8,after:4,riskResult:null,saved:false};ccRenderStudio();}
function ccRenderStudio(){if(!ccStudio)return;const s=CC_STUDIOS.find(x=>x.id===ccStudio.id);let html='';if(s.mode==='sequence')html=ccSequenceHTML(s);if(s.mode==='decisions')html=ccDecisionsHTML(s);if(s.mode==='match')html=ccMatchHTML(s);if(s.mode==='risk')html=ccRiskHTML(s);showModal(s.title,'Original fictional learning Studio · At your pace',ccStudioHeader(s)+html+ccInlineGuide(s.id));document.getElementById('modal').classList.add('tool-workspace');}
function ccInlineGuide(key){return ccFacilitatorNotes(key);}
function ccFacilitatorNotes(key){const g=ccGuideFor(key),u=ccUsage(key);return `<details class="cc-facilitator-notes"><summary>${hcaIcon('reflect')} Facilitation & reflection notes</summary><div><h4>Why practise this?</h4><p>${esc(g.why)}</p><div class="cc-brief-grid"><section><h4>Useful when</h4><p>${esc(u.when)}</p></section><section><h4>Who can take part</h4><p>${esc(u.who)}</p></section></div><p>After the activity, ask: what did your first response leave unclear, and what would you do differently next time?</p><button class="text-link" data-action="engine-30" data-engine-30="${esc(JSON.stringify([g.evidence]))}">Read the supporting research →</button></div></details>`;}
function ccUsage(key){const l=lessons.find(x=>x.id===key),g=ccGuideFor(key),u=CC_USE[l?.id];return {who:u?.[0]||g.who,when:u?.[1]||g.when,action:l?P2_DATA.examples[l.id].action:g.how};}
function ccStudioHeader(s){return ccActivityBrief(s.id);}
function ccActivityBrief(key){const g=ccGuideFor(key);return `<section class="cc-activity-brief" aria-label="Activity instructions"><div class="cc-activity-intro">${hcaIcon('route')}<div><strong>How to use this activity</strong><p>${esc(g.how)}</p></div></div><div class="cc-activity-meta"><span>${hcaIcon('clock')} At your pace</span><span>${hcaIcon('team')} Individual or facilitated practice</span><button class="text-link" data-action="engine-30" data-engine-30="${esc(JSON.stringify([g.evidence]))}">${hcaIcon('research')} Research context →</button></div></section>`;}
function ccSequenceHTML(s){const a=ccStudio;return `<div class="cc-studio-head"><span class="eyebrow">BUILD A USEFUL SEQUENCE</span><p>${s.intro}</p></div><p>Select each move in the order you would use it. You can undo before checking.</p><div class="cc-sequence">${(s.steps.length===5?[3,0,4,2,1]:[2,0,3,1]).map(i=>`<button data-action="engine-31" data-engine-31="${esc(JSON.stringify([i]))}" ${a.order.includes(i)||a.checked?'disabled':''}>${s.steps[i]}</button>`).join('')}</div><div class="cc-order-selected" aria-live="polite"><strong>Your sequence · ${a.order.length}/${s.steps.length}</strong>${a.order.map((n,i)=>`<p>${i+1}. ${s.steps[n]}</p>`).join('')}</div><div class="modal-actions"><button class="btn secondary" ${!a.order.length||a.checked?'disabled':''} data-action="engine-32" data-engine-32="[]">Undo last move</button><button class="btn" ${a.order.length!==s.steps.length||a.checked?'disabled':''} data-action="engine-33" data-engine-33="[]">Check my sequence</button></div>${a.checked?`<div class="cc-studio-report" role="status"><h4>${a.order.every((n,i)=>n===i)?'A coherent sequence.':'Compare the dependencies.'}</h4><p>${s.why} The later check needs an explanation first; a repair needs the gap to be understood.</p><ol>${s.steps.map(t=>`<li>${t}</li>`).join('')}</ol></div>${ccStudioActions(s)}`:''}`;}
function ccSequencePick(i){if(!ccStudio||ccStudio.checked||ccStudio.order.includes(i))return;ccStudio.order.push(i);ccRenderStudio();requestAnimationFrame(()=>{const next=document.querySelector('.cc-sequence>button:not(:disabled)')||document.querySelector('#modalBody .modal-actions .btn:not(.secondary)');next?.focus({preventScroll:true});});}
function ccStudioActions(s){return `<div class="modal-actions"><button class="btn secondary" data-action="engine-34" data-engine-34="${esc(JSON.stringify([s.id]))}">Try a fresh attempt</button><button class="btn" ${ccStudio.saved?'disabled':''} data-action="engine-35" data-engine-35="[]">${ccStudio.saved?'Attempt saved ✓':'Save this practice attempt'}</button><button class="text-link" data-action="engine-36" data-engine-36="${esc(JSON.stringify([s.lesson]))}">Related lesson →</button></div>`;}
function ccSaveStudio(){if(!ccStudio)return;const s=CC_STUDIOS.find(x=>x.id===ccStudio.id),a=ccStudio;if(a.saved||!ccStudioComplete(s,a)){toast('Complete the activity and review its feedback before saving.');return;}let detail=s.mode==='decisions'?a.history.map((h,i)=>`${i+1}. ${h.choice}\n${h.feedback}`).join('\n\n'):s.mode==='sequence'?a.order.map((n,i)=>(i+1)+'. '+s.steps[n]).join('\n')+'\nReviewed the intended sequence.':s.mode==='match'?s.rows.map((r,i)=>r[0]+': '+a.classified[i]).join('\n')+'\nReviewed discrepancy verification and ownership.':`Synthetic risks ${a.baseline}/100 and ${a.after}/100. Absolute reduction: ${ccRiskValues(a.baseline,a.after).absolute.toFixed(1)} percentage points; relative reduction: ${ccRiskValues(a.baseline,a.after).relative.toFixed(1)}%. Reviewed the calculation. First calculation matched: ${a.riskResult?'yes':'no'}.`;logStudio(s.id,s.title,detail+'\nOriginal fictional learning activity, not verified clinical performance.');a.saved=true;ccRenderStudio();}
function ccRiskValues(b,a){const absolute=b-a;return {absolute,relative:100*absolute/b};}
function ccStudioComplete(s,a){return s.mode==='decisions'?a.index>=s.scenes.length:s.mode==='sequence'?a.checked&&a.order.length===s.steps.length:s.mode==='match'?a.checked&&a.classified.filter(Boolean).length===s.rows.length:a.checked;}
function ccDecisionsHTML(s){const a=ccStudio;if(a.index>=s.scenes.length)return `<div class="cc-studio-head"><span class="eyebrow">YOUR DECISION TRAIL</span><h3>${a.history.filter(x=>x.correct).length} of ${s.scenes.length} first choices recognised.</h3><p>Read the reasoning, including where you changed direction. This is learning activity, not a competency score.</p></div>${a.history.map((h,i)=>`<div class="cc-studio-report"><h4>${i+1}. ${s.scenes[i][0]}</h4><p>You selected: ${esc(h.choice)}</p><p>${esc(h.feedback)}</p><p>Stronger approach: ${s.scenes[i][3][s.scenes[i][4]]}</p></div>`).join('')}${ccStudioActions(s)}`;
 const q=s.scenes[a.index],answered=a.selected!==null;return `<div class="cc-step-dots" aria-hidden="true">${s.scenes.map((_,i)=>`<i class="${i<=a.index?'on':''}"></i>`).join('')}</div><span class="eyebrow">MOMENT ${a.index+1} OF ${s.scenes.length}</span><div class="cc-studio-head"><h3>${q[0]}</h3><p>${q[1]}</p></div><p class="question">${q[2]}</p>${q[3].map((t,i)=>`<button class="answer ${answered&&i===q[4]?'correct':''} ${a.selected===i&&i!==q[4]?'incorrect':''}" ${answered?'disabled':''} data-action="engine-37" data-engine-37="${esc(JSON.stringify([i]))}"><span class="letter">${'ABC'[i]}</span><span>${t}</span></button>`).join('')}<div aria-live="polite">${answered?`<div class="feedback ${a.selected===q[4]?'good':''}"><strong>${a.selected===q[4]?'A useful direction.':'Notice what remains unresolved.'}</strong>${q[5][a.selected]}</div><details><summary>Why each option matters</summary>${q[3].map((t,i)=>`<p><b>${'ABC'[i]}.</b> ${q[5][i]}</p>`).join('')}</details>`:''}</div><div class="modal-actions"><button class="btn" ${answered?'':'disabled'} data-action="engine-38" data-engine-38="[]">${a.index===s.scenes.length-1?'See my debrief':'Next moment'} →</button></div>`;}
function ccDecisionAnswer(i){if(!ccStudio||ccStudio.selected!==null)return;const s=CC_STUDIOS.find(x=>x.id===ccStudio.id),q=s.scenes?.[ccStudio.index];if(!q||!q[3][i])return;ccStudio.selected=i;ccStudio.history.push({choice:q[3][i],correct:i===q[4],feedback:q[5][i]});ccRenderStudio();}
function ccDecisionNext(){if(ccStudio.selected===null)return;ccStudio.index++;ccStudio.selected=null;ccRenderStudio();}
function ccMatchHTML(s){const a=ccStudio;return `<div class="cc-studio-head"><h3>Compare, then verify.</h3><p>These are intentionally incomplete fictional records, not a medication plan. Classifying a mismatch does not authorise starting, stopping or changing anything.</p></div><div class="cc-stage-grid"><div class="cc-stage-card"><h4>Sending list</h4>${s.rows.map(r=>`<p><b>${r[0]}:</b> ${r[1]}</p>`).join('')}</div><div class="cc-stage-card"><h4>Receiving list</h4>${s.rows.map(r=>`<p><b>${r[0]}:</b> ${r[2]}</p>`).join('')}</div></div>${s.rows.map((r,i)=>`<div class="cc-match-row"><label for="ccMatch${i}">${r[0]} · How would you classify these records?</label><select id="ccMatch${i}" ${a.checked?'disabled':''} data-onchange="engine-39" data-engine-39="${esc(JSON.stringify([i]))}"><option value="">Choose a classification</option>${s.options.map(t=>`<option ${a.classified[i]===t?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')}<div class="modal-actions"><button class="btn" ${a.checked?'disabled':''} data-action="engine-40" data-engine-40="[]">Compare my classifications</button></div>${a.checked?`<div class="cc-studio-report" role="status"><h4>${s.rows.filter((r,i)=>a.classified[i]===r[3]).length} of 3 classifications match.</h4>${s.rows.map((r,i)=>`<p><b>${r[0]}:</b> ${r[3]}. ${i<2?'Clarify with the responsible clinician or pharmacist using the approved reconciliation process.':'Agreement between these two entries alone does not validate the whole plan.'}</p>`).join('')}<p>Communicate the verified resolution and make ownership of any unresolved question explicit.</p></div>${ccStudioActions(s)}`:''}`;}
function ccCheckMatch(){const s=CC_STUDIOS.find(x=>x.id===ccStudio?.id);if(!s||ccStudio.checked)return;if(!s.rows.every((_,i)=>s.options.includes(ccStudio.classified[i]))){toast('Choose a classification for all three rows first.');return;}ccStudio.checked=true;ccRenderStudio();}
function ccRiskHTML(s){const a=ccStudio,r=ccRiskValues(a.baseline,a.after);return `<div class="cc-studio-head"><h3>Two fictional groups. One consistent comparison.</h3><p>Both figures describe the same outcome per 100 people over the same fictional period. Change the figures and calculate the percentage-point reduction and relative percentage reduction. A negative answer represents an increase.</p></div><label class="cc-slider" for="ccBaseline">Starting risk: <output id="ccBaselineValue">${a.baseline}</output> in 100<input id="ccBaseline" type="range" min="1" max="40" value="${a.baseline}" data-oninput="engine-41" data-engine-41="[]"></label><label class="cc-slider" for="ccAfter">Comparison risk: <output id="ccAfterValue">${a.after}</output> in 100<input id="ccAfter" type="range" min="0" max="40" value="${a.after}" data-oninput="engine-42" data-engine-42="[]"></label><div class="cc-risk-display" id="ccRiskFigures">${ccRiskFigures(a)}</div><div class="cc-stage-grid" style="margin-top:20px"><div class="form-group"><label for="ccAbsolute">Percentage-point reduction (start minus comparison)</label><input id="ccAbsolute" type="number" step="any" placeholder="Enter your calculation" value="${a.absoluteAnswer??''}" data-oninput="engine-43" data-engine-43="[]"></div><div class="form-group"><label for="ccRelative">Relative percentage reduction</label><input id="ccRelative" type="number" step="any" placeholder="Enter your calculation" value="${a.relativeAnswer??''}" data-oninput="engine-44" data-engine-44="[]"></div></div><button class="btn" data-action="engine-45" data-engine-45="[]">Check the comparison</button><div id="ccRiskResult" aria-live="polite">${a.checked?`<div class="cc-studio-report"><h4>${a.riskResult?'Both calculations match.':'Compare the two ways of describing change.'}</h4><p><b>${r.absolute.toFixed(1)} percentage points</b> = ${a.baseline}% − ${a.after}%.<br><b>${r.relative.toFixed(1)}% relative reduction</b> = (${a.baseline} − ${a.after}) ÷ ${a.baseline} × 100.</p><p>${r.absolute<0?'This example is an increase, so both reduction values are negative.':r.absolute===0?'There is no difference in this example.':'Use the baseline and absolute difference alongside the relative percentage.'} These synthetic numbers are not clinical evidence or a treatment recommendation.</p></div>${ccStudioActions(s)}`:''}</div>`;}
function ccRiskFigures(a){return [[a.baseline,'Starting risk'],[a.after,'Comparison risk']].map(([v,t])=>`<div class="cc-risk-numbers"><strong>${v} / 100</strong><span>${t}</span><div class="cc-risk-dots" aria-hidden="true">${Array.from({length:100},(_,i)=>`<i class="${i<v?'on':''}"></i>`).join('')}</div></div>`).join('');}
function ccRiskChange(k,v){if(!ccStudio||!['baseline','after'].includes(k))return;const n=Number(v);if(!Number.isFinite(n))return;ccStudio[k]=Math.max(k==='baseline'?1:0,Math.min(40,n));ccStudio.checked=false;ccStudio.saved=false;ccStudio.absoluteAnswer='';ccStudio.relativeAnswer='';const output=document.getElementById(k==='baseline'?'ccBaselineValue':'ccAfterValue');if(output)output.textContent=ccStudio[k];const figures=document.getElementById('ccRiskFigures');if(figures)figures.innerHTML=ccRiskFigures(ccStudio);const result=document.getElementById('ccRiskResult');if(result)result.innerHTML='';for(const id of ['ccAbsolute','ccRelative']){const e=document.getElementById(id);if(e)e.value='';}}
function ccCheckRisk(){if(!ccStudio)return;const a=ccStudio;if(a.absoluteAnswer===undefined||a.relativeAnswer===undefined||a.absoluteAnswer===''||a.relativeAnswer===''){toast('Enter both calculations before checking.');return;}const r=ccRiskValues(a.baseline,a.after);a.riskResult=Math.abs(Number(a.absoluteAnswer)-r.absolute)<.11&&Math.abs(Number(a.relativeAnswer)-r.relative)<.11;a.checked=true;ccRenderStudio();}
function ccOpenSimulation(id){const s=CC_SIMS.find(x=>x.id===id);if(!s)return;ccCurrentGuide=id;ccSim={id,zone:0,answers:[null,null,null],maps:s.zones.map(z=>hcaShuffle(z.answers.length)),flat:studioReducedMotion(),angle:-30,zoom:1,playing:false,saved:false,finished:false};ccRenderSimulation();}
function ccRenderSimulation(){if(!ccSim)return;const s=CC_SIMS.find(x=>x.id===ccSim.id),a=ccSim,z=s.zones[a.zone],choice=a.answers[a.zone],complete=a.answers.every(v=>v!==null);let work=a.finished?`<div class="cc-studio-head"><span class="eyebrow">YOUR COMPLETE DECISION TRAIL</span><h3>${a.answers.filter((v,i)=>v===s.zones[i].correct).length} of 3 first choices recognised.</h3><p>Read what your choices made explicit and what still needed attention. This is a learning record, not a competency assessment.</p></div>${s.zones.map((q,i)=>`<section class="cc-studio-report"><h4>${i+1}. ${q.name}</h4><p>You chose: ${esc(q.answers[a.answers[i]])}</p><p>${esc(q.why[a.answers[i]])}</p><p><strong>Stronger response:</strong> ${esc(q.answers[q.correct])}</p></section>`).join('')}<div class="modal-actions"><button class="btn" ${a.saved?'disabled':''} data-action="engine-46" data-engine-46="[]">${a.saved?'Attempt saved ✓':'Save simulation attempt'}</button><button class="btn secondary" data-action="engine-47" data-engine-47="${esc(JSON.stringify([s.id]))}">Try a fresh rehearsal</button><button class="text-link" data-action="engine-36" data-engine-36="${esc(JSON.stringify([s.lesson]))}">Related lesson →</button></div>`:`<div class="cc-sim-layout"><div>${ccSimScene(s)}<div class="cc-sim-hotspot-list" role="group" aria-label="Simulation checkpoints">${s.zones.map((q,i)=>`<button class="${i===a.zone?'active':''}" aria-pressed="${i===a.zone}" data-action="engine-48" data-engine-48="${esc(JSON.stringify([i]))}"><b>${a.answers[i]!==null?'✓':i+1}</b><span>${q.name}</span></button>`).join('')}</div><div class="cc-sim-caption">${a.answers.filter(v=>v!==null).length} of 3 checkpoints reviewed. All content is also available through the buttons.</div></div><section class="cc-sim-task"><span class="eyebrow">CHECKPOINT ${a.zone+1} / 3 · ${z.label}</span><h3>${z.name}</h3><p>${z.copy}</p>${s.theme==='conversation'&&a.zone===1?ccSimRiskBoard():''}<p class="question">${z.question}</p>${a.maps[a.zone].map((original,i)=>`<button class="answer ${choice!==null&&original===z.correct?'correct':''} ${choice===original&&original!==z.correct?'incorrect':''}" ${choice!==null?'disabled':''} data-action="engine-49" data-engine-49="${esc(JSON.stringify([i]))}"><span class="letter">${'ABC'[i]}</span><span>${z.answers[original]}</span></button>`).join('')}<div aria-live="polite">${choice!==null?`<div class="feedback ${choice===z.correct?'good':''}"><strong>${choice===z.correct?'A clearer next action.':'Notice the remaining gap.'}</strong>${z.why[choice]}</div>`:''}</div><div class="modal-actions"><button class="btn" ${choice===null?'disabled':''} data-action="engine-50" data-engine-50="[]">${complete?'Open my debrief':'Next checkpoint'} →</button></div></section></div>`;
 showModal(s.title,'Graphical simulation · Three fictional checkpoints',`<figure class="cc-sim-art"><img src="${CC_SIM_ART[s.image]}" alt="Original HCA illustration: ${esc(s.title)}"><figcaption>Original AI-generated illustration · Fictional setting</figcaption></figure>${ccActivityBrief(s.id)}${work}${ccInlineGuide(s.id)}`);document.getElementById('modal').classList.add('cc-sim-modal');}
function ccSimScene(s){return `<div class="cc-sim-viewport ${ccSim.flat?'is-flat':''} ${ccSim.playing?'is-playing':''}" id="ccSimViewport"><div class="cc-sim-stage" id="ccSimStage" style="transform:translate(-50%,-50%) rotateX(54deg) rotateZ(${ccSim.angle}deg) scale(${ccSim.zoom})"><div class="cc-sim-floor"></div><div class="cc-sim-wall back"></div><div class="cc-sim-wall side"></div>${ccSimShapes(s.theme)}<div class="cc-sim-signal" aria-hidden="true"></div>${s.zones.map((z,i)=>`<button class="cc-sim-node ${i===ccSim.zone?'selected':''} ${ccSim.answers[i]!==null?'reviewed':''}" style="left:${z.x}px;top:${z.y}px" aria-label="Explore checkpoint ${i+1}: ${z.name}" aria-pressed="${i===ccSim.zone}" data-action="engine-48" data-engine-48="${esc(JSON.stringify([i]))}">${ccSim.answers[i]!==null?'✓':i+1}</button>`).join('')}</div><span class="cc-sim-caption">CSS 3D teaching model · Not to scale</span></div><div class="cc-sim-view-controls"><button class="btn secondary" data-action="engine-51" data-engine-51="[]">${ccSim.flat?'Show 3D room':'Use text view'}</button><button class="btn secondary" ${studioReducedMotion()?'disabled':''} aria-pressed="${ccSim.playing}" data-action="engine-52" data-engine-52="[]">${ccSim.playing?'Pause':'Play'} communication signal</button></div><div class="cc-sim-ranges"><label for="ccSimAngle">Rotate viewpoint<input type="range" id="ccSimAngle" min="-65" max="15" step="1" value="${ccSim.angle}" data-oninput="engine-53" data-engine-53="[]"></label><label for="ccSimZoom">Zoom<input type="range" id="ccSimZoom" min="0.75" max="1.2" step="0.05" value="${ccSim.zoom}" data-oninput="engine-54" data-engine-54="[]"></label></div>`;}
function ccSimShapes(theme){if(theme==='bedside')return '<div class="cc-solid sim-bed"><i></i></div><div class="cc-solid sim-board"><i></i><i></i><i></i></div><div class="cc-solid sim-workstation"><i></i></div><div class="cc-solid sim-stool"></div>';if(theme==='desk')return '<div class="cc-solid sim-desk"><i class="sim-folder"></i><i class="sim-tray"></i></div><div class="cc-solid sim-inbox"><i></i><i></i></div><div class="cc-solid sim-phone"></div><div class="cc-solid sim-seat"></div>';return '<div class="cc-solid sim-chair left"></div><div class="cc-solid sim-chair right"></div><div class="cc-solid sim-table"></div><div class="cc-solid sim-number-board"><i></i><i></i><i></i><i></i><i></i></div>';}
function ccSimZone(i){if(!ccSim||!Number.isInteger(i)||i<0||i>2)return;ccSim.zone=i;ccRenderSimulation();}
function ccSimView(key,v){if(!ccSim)return;const n=Number(v);if(!Number.isFinite(n)||!['angle','zoom'].includes(key))return;ccSim[key]=key==='angle'?Math.max(-65,Math.min(15,n)):Math.max(.75,Math.min(1.2,n));const stage=document.getElementById('ccSimStage');if(stage)stage.style.transform=`translate(-50%,-50%) rotateX(54deg) rotateZ(${ccSim.angle}deg) scale(${ccSim.zoom})`;}
function ccSimMotion(){const el=document.getElementById('ccSimViewport');el?.classList.toggle('is-playing',ccSim.playing&&!studioReducedMotion());const button=document.querySelector('.cc-sim-view-controls button[aria-pressed]');if(button){button.setAttribute('aria-pressed',ccSim.playing);button.textContent=(ccSim.playing?'Pause':'Play')+' communication signal';}}
function ccSimRiskBoard(){return `<div class="cc-sim-risk-board" aria-label="Synthetic comparison: eight versus five in one hundred over the same period">${[[8,'8 in 100'],[5,'5 in 100']].map(([n,t])=>`<div><strong>${t}</strong><div class="cc-risk-dots" aria-hidden="true">${Array.from({length:100},(_,i)=>`<i class="${i<n?'on':''}"></i>`).join('')}</div></div>`).join('')}<small>Synthetic example · Same outcome and time period</small></div>`;}
function ccSimAnswer(displayIndex){if(!ccSim||ccSim.answers[ccSim.zone]!==null)return;const original=ccSim.maps[ccSim.zone][displayIndex];if(!Number.isInteger(original))return;ccSim.answers[ccSim.zone]=original;ccRenderSimulation();}
function ccSimNext(){if(!ccSim||ccSim.answers[ccSim.zone]===null)return;if(ccSim.answers.every(v=>v!==null))ccSim.finished=true;else{const next=[1,2,3].map(n=>(ccSim.zone+n)%3).find(i=>ccSim.answers[i]===null);ccSim.zone=next;}ccRenderSimulation();}
function ccSaveSimulation(){if(!ccSim||ccSim.saved||!ccSim.finished||!ccSim.answers.every(v=>v!==null)){toast('Review all three checkpoints and open the debrief before saving.');return;}const s=CC_SIMS.find(x=>x.id===ccSim.id),detail=s.zones.map((z,i)=>`${i+1}. ${z.name}\nSelected: ${z.answers[ccSim.answers[i]]}\n${z.why[ccSim.answers[i]]}`).join('\n\n');logStudio(s.id,s.title,detail+'\nFictional graphical rehearsal; not verified clinical performance.');ccSim.saved=true;ccRenderSimulation();}
function hcaOpenRoom(){hcaRoom={index:0,selected:null,answers:[],zone:0,flat:studioReducedMotion(),angle:-35,zoom:1};hcaRenderRoom();}
function hcaRenderRoom(){const done=hcaRoom.index>=6,s=hygieneScenes[Math.min(5,hcaRoom.index)];let body=done?`<div class="takeaway"><div class="eyebrow">YOUR LEARNING DEBRIEF</div><h3>${hcaRoom.answers.filter(Boolean).length} of 6 first choices recognized.</h3><p>A practice result, not a measure of clinical competence.</p></div>${hygieneScenes.map((s,i)=>`<div class="hca-trail"><h4>${s.title}</h4><p>${s.feedback}</p><small>${hcaRoom.answers[i]?'Recognized on first choice':'Reviewed with feedback'}</small></div>`).join('')}<div class="modal-actions"><button class="btn secondary" data-action="engine-55" data-engine-55="[]">Try again</button><button class="btn" data-action="engine-56" data-engine-56="${esc(JSON.stringify([hcaRoom.answers.filter(Boolean).length]))}">Save this practice attempt →</button></div>`:`<div class="room-progress"><span>VIGNETTE ${hcaRoom.index+1} / 6</span><button class="text-link" data-action="engine-57" data-engine-57="[]">${hcaRoom.flat?'Show 3D illustration':'Use the text view'}</button></div><div class="${hcaRoom.flat?'room-flat':''}"><div class="room-layout"><div>${hcaRoomHTML()}<div class="room-controls"><label for="roomAngle">Rotate the room<input id="roomAngle" type="range" min="-65" max="20" step="1" value="${hcaRoom.angle}" data-oninput="engine-58" data-engine-58="[]"></label><label for="roomZoom">Zoom<input id="roomZoom" type="range" min="0.75" max="1.2" step="0.05" value="${hcaRoom.zoom}" data-oninput="engine-59" data-engine-59="[]"></label></div><div class="room-hotspot-list" role="group" aria-label="Care room zones">${HCA_ROOM_ZONES.map(([t],i)=>`<button aria-pressed="${i===hcaRoom.zone}" class="${i===hcaRoom.zone?'active':''}" data-action="engine-60" data-engine-60="${esc(JSON.stringify([i]))}">${i+1}. ${t}</button>`).join('')}</div><div class="hca-source-panel" id="roomZoneNote" role="status"><strong>${HCA_ROOM_ZONES[hcaRoom.zone][0]}</strong><p>${HCA_ROOM_ZONES[hcaRoom.zone][1]}</p></div><p class="room-figure-caption">Original CSS 3D illustration. Simplified geometry and fictional context; no motion tracking or clinical technique validation.</p></div><div><div class="room-vignette"><div class="eyebrow">PAUSE & REASON</div><h3>${s.title}</h3><p>${s.context}</p></div><p class="question">Which indication best fits this moment?</p><div>${hygieneMoments.map((m,i)=>`<button class="answer ${hcaRoom.selected!==null&&i===s.correct?'correct':''} ${hcaRoom.selected===i&&i!==s.correct?'incorrect':''}" ${hcaRoom.selected!==null?'disabled':''} data-action="engine-61" data-engine-61="${esc(JSON.stringify([i]))}"><span>${m}</span></button>`).join('')}</div><div class="room-result" aria-live="polite">${hcaRoom.selected!==null?`<div class="feedback ${hcaRoom.selected===s.correct?'good':''}"><strong>${hcaRoom.selected===s.correct?'A well-placed pause.':'Look again at the indication.'}</strong>${s.feedback}</div>`:''}</div><div class="modal-actions"><button class="btn" ${hcaRoom.selected===null?'disabled':''} data-action="engine-62" data-engine-62="[]">${hcaRoom.index===5?'See my debrief':'Next vignette'} →</button></div></div></div></div>`;showModal('The room. The pause. The decision.','An illustrated care-room explorer · Hand-hygiene indications',body+`<div class="adv-source">Independent fictional vignettes informed by <a href="${STUDIO_SOURCES.who.url}" target="_blank" rel="noopener noreferrer">WHO Five Moments resources ↗</a>. Read the scenario; markers do not show detected contamination. Follow current local policy.</div>`);$('#modal').classList.add('tool-workspace');}
function hcaRoomHTML(){return `<div class="room-viewport" aria-label="Illustrated 3D care room. Equivalent zones and complete vignette text follow."><div class="room-stage" id="roomStage" style="transform:translate(-50%,-50%) rotateX(57deg) rotateZ(${hcaRoom.angle}deg) scale(${hcaRoom.zoom})"><div class="room-floor"></div><div class="room-wall back"></div><div class="room-wall side"></div><div class="room-bed"><div class="room-pillow"></div><div class="room-person"></div></div><div class="room-table"></div><div class="room-tray"></div><div class="room-sink"></div>${[[151,113],[64,42],[190,167],[231,49],[27,168]].map(([x,y],i)=>`<button class="room-node ${hcaRoom.zone===i?'active':''}" style="left:${x}px;top:${y}px" aria-label="Explore ${HCA_ROOM_ZONES[i][0]}" data-action="engine-60" data-engine-60="${esc(JSON.stringify([i]))}">${i+1}</button>`).join('')}</div><span class="illustrative-tag" style="color:var(--muted);border-color:#10253a50;background:var(--surface)">ILLUSTRATIVE · NOT TO SCALE</span></div>`;}
function hcaRoomZone(i){hcaRoom.zone=i;const e=$('#roomZoneNote');if(e)e.innerHTML=`<strong>${HCA_ROOM_ZONES[i][0]}</strong><p>${HCA_ROOM_ZONES[i][1]}</p>`;document.querySelectorAll('.room-node').forEach((b,j)=>b.classList.toggle('active',i===j));document.querySelectorAll('.room-hotspot-list button').forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',i===j)});}
function hcaRotateRoom(v){hcaRoom.angle=Number(v);hcaRoomTransform();}
function hcaRoomTransform(){const e=$('#roomStage');if(e)e.style.transform=`translate(-50%,-50%) rotateX(57deg) rotateZ(${hcaRoom.angle}deg) scale(${hcaRoom.zoom})`;}
function hcaZoomRoom(v){hcaRoom.zoom=Number(v);hcaRoomTransform();}
function hcaAnswerRoom(i){if(hcaRoom.selected!==null)return;hcaRoom.selected=i;hcaRoom.answers[hcaRoom.index]=i===hygieneScenes[hcaRoom.index].correct;hcaRenderRoom();}
function renderCase(){if(!branchSession)return;if(branchSession.stage>=3){finishBranch();return}const c=cases.find(c=>c.id===branchSession.case),q=branchQuestion(),answered=branchSession.selected!==null;showModal(c.title,`Fictional branching practice · Decision ${branchSession.stage+1} of 3`,`<div class="scenario-progress">${[0,1,2].map(i=>`<span class="${i<=branchSession.stage?'done':''}"></span>`).join('')}</div><div class="scenario-event">${q.event}</div><p class="question">${q.question}</p><div id="caseAnswers">${q.answers.map((a,i)=>`<button class="answer ${answered&&i===q.correct?'correct':''} ${answered&&i===branchSession.selected&&i!==q.correct?'incorrect':''}" ${answered?'disabled':''} data-action="engine-63" data-engine-63="${esc(JSON.stringify([i]))}"><span class="letter">${'ABC'[i]}</span><span>${a}</span></button>`).join('')}</div><div aria-live="polite">${answered?`<div class="feedback ${branchSession.selected===q.correct?'good':''}"><strong>${branchSession.selected===q.correct?'A useful direction.':'Notice what remains unresolved.'}</strong>${q.rationales[branchSession.selected]}</div><details><summary style="cursor:pointer;min-height:44px">Explore the reasoning for all choices</summary>${q.rationales.map((r,i)=>`<div class="choice-explanation"><strong>${'ABC'[i]}</strong>${r}</div>`).join('')}</details>`:''}</div><div class="modal-actions"><button class="btn" id="nextCase" ${answered?'':'disabled'} data-action="engine-64" data-engine-64="[]">${branchSession.stage===2?'See my debrief':'Follow the next moment'} →</button></div>`);}
function answerCase(i){if(!branchSession||branchSession.selected!==null)return;const q=branchQuestion();if(i<0||i>=q.answers.length)return;branchSession.selected=i;const helpful=i===q.correct;if(branchSession.stage===0)branchSession.firstHelpful=helpful;branchSession.path.push({stage:branchSession.stage,label:q.answers[i],helpful,feedback:q.rationales[i]});renderCase();}
function openAdv(id){advStop();advMode=id;if(id==='cus'){cusStep=0;cusSelected=null;cusHistory=[];renderCus();}if(id==='huddle'){huddleStep=0;huddleHistory=[];renderHuddle();}if(id==='flow'){resetFlow();renderFlow();}}
function advStop(){clearInterval(advTimer);advTimer=null;advPlaying=false;const scene=$('#advScene');if(scene)scene.classList.remove('playing');const b=$('#advPlay');if(b){b.textContent='Play';b.setAttribute('aria-pressed','false');}}
function renderCus(){const s=cusScenes[cusStep],answered=cusSelected!==null;advFrame('Speak up with clarity','Fictional CUS communication practice',`<div class="notice">CUS is a communication framework, not a mandatory waiting sequence. Escalate urgent risks immediately through local procedures.</div><div class="adv-scene" id="advScene"><div class="adv-signal" aria-hidden="true"></div><div class="adv-stage"><div class="adv-person"><h4>Concern raised</h4><p id="advFrameText">${s.event}</p></div><div class="adv-person"><h4>Shared understanding</h4><p>${answered&&cusSelected===s.good?'The gap is more explicit. Agree on the required next action.':'What needs to be made clear before you move on?'}</p></div></div><div class="adv-ladder">${[['C','Concerned'],['U','Uncomfortable'],['S','Safety issue']].map(([c,t],i)=>`<div class="adv-rung ${i<=cusStep?'active':''}"><b>${c}</b><p>${t}</p></div>`).join('')}</div></div>${advPlayback()}<h3>${s.title}</h3><div class="adv-choices" style="margin-top:14px">${s.options.map((t,i)=>`<button ${answered?'disabled':''} data-action="engine-65" data-engine-65="${esc(JSON.stringify([i]))}">${'ABC'[i]} · ${t}</button>`).join('')}</div><div aria-live="polite">${answered?`<div class="feedback ${cusSelected===s.good?'good':''}"><strong>${cusSelected===s.good?'A clearer concern.':'Notice the unresolved gap.'}</strong>${s.why[cusSelected]}</div><button class="btn" data-action="engine-66" data-engine-66="[]">${cusStep===2?'See my debrief':'Next moment'} →</button>`:''}</div>`,'team');}
function advFrame(title,sub,content,source){showModal(title,sub,content+advCitation(source));$('#modal').classList.add('tool-workspace');}
function advCitation(id){return `<div class="adv-source">Original Carecraft educational activity. Inspired by the structure of <a href="${advSources[id]||advSources.qi}" target="_blank" rel="noopener noreferrer">${id==='team'?'AHRQ CUS':id==='desc'?'AHRQ DESC':id==='huddle'?'AHRQ team leadership tools':'IHI quality-improvement tools'} ↗</a>. No affiliation, endorsement, or independently validated score is implied.</div>`;}
function advPlayback(){return `<div class="adv-control-row"><button class="btn secondary" id="advPlay" aria-pressed="false" data-action="engine-67" data-engine-67="[]">Play</button><button class="btn secondary" data-action="engine-68" data-engine-68="[]">Step →</button><button class="text-link" data-action="engine-69" data-engine-69="${esc(JSON.stringify([advMode]))}">Restart</button><small class="muted">${studioReducedMotion()?'Reduced motion: use Step; playback remains optional.':'Playback starts only when you choose.'}</small></div>`;}
function advToggle(){if(advPlaying){advStop();return}advPlaying=true;$('#advScene')?.classList.add('playing');const b=$('#advPlay');if(b){b.textContent='Pause';b.setAttribute('aria-pressed','true');}if(advMode==='flow'){advTimer=setInterval(()=>{if(simStep>=12){advStop();return}stepFlow();},850);}}
function stepFlow(){if(simStep>=12){advStop();return}simStep++;simQueue+=4;const processed=Math.min(simCapacity,simQueue);simQueue-=processed;const returned=simStep%3===0&&processed>0?1:0;simQueue+=returned;simServed+=processed-returned;simRework+=returned;simHistory.push({step:simStep,queue:simQueue,completed:simServed,rework:simRework});$('#flowNumbers').innerHTML=flowSummary();if(simStep>=12)advStop();}
function flowSummary(){return `<div class="adv-flow"><div><strong>${simQueue}</strong><span>Items waiting</span><div class="adv-dot-row">${Array.from({length:Math.min(simQueue,18)},()=>'<i></i>').join('')}</div></div><div><strong>${simServed}</strong><span>Items completed</span><div class="adv-dot-row">${Array.from({length:Math.min(simServed,18)},()=>'<i></i>').join('')}</div></div><div><strong>${simRework}</strong><span>Items returned for rework</span><div class="adv-dot-row">${Array.from({length:Math.min(simRework,18)},()=>'<i></i>').join('')}</div></div></div><p class="field-hint">Step ${simStep} / 12 · Four new items arrive per step. Capacity = ${simCapacity}. Every third step, one processed item returns to the queue.</p>`;}
function advNextFrame(){advStop();if(advMode==='flow')stepFlow();else if(advMode==='huddle')huddleAdvance();else{const el=$('#advFrameText');if(el)el.textContent=['Pause: notice the observed concern.','Name the unresolved uncertainty.','Request a response and confirm the next action.'][cusStep];}}
function huddleAdvance(){advStop();huddleStep=(huddleStep+1)%3;renderHuddle();}
function renderHuddle(){advFrame('Bring the team into alignment','A fictional staff-learning session, not clinical staffing',`<p>Use Brief → Huddle → Debrief to make ownership and changing conditions visible.</p><div class="adv-scene" id="advScene"><div class="adv-timeline">${['Brief','Huddle','Debrief'].map((t,i)=>`<div class="${huddleStep>=i?'active':''}"><b>${t}</b></div>`).join('')}</div><div class="adv-board">${['Shared tasks','Named ownership','Changed conditions & response'].map((t,i)=>`<section class="adv-lane"><h4>${t}</h4>${huddleTasks.map(task=>`<div class="adv-task"><p>${i===0?task.name:i===1?(huddleStep>=1?task.owner+' owns '+task.name.toLowerCase():'Owner not yet confirmed'):(huddleStep>=1?task.constraint+' '+task.backup:'Watch for changes before starting.')}</p></div>`).join('')}</section>`).join('')}</div><p id="advFrameText" class="field-hint">${['Brief: identify the tasks and ask who owns each action.','Huddle: share what changed and adjust the plan together.','Debrief: compare what happened with the plan and identify one change for next time.'][Math.min(huddleStep,2)]}</p></div><div class="adv-control-row"><button class="btn secondary" data-action="engine-70" data-engine-70="[]">${huddleStep<2?'Reveal the next stage':'Replay the board'} →</button><button class="btn secondary" data-action="engine-71" data-engine-71="[]">Open my editable board</button></div><h3>Choose the useful team response</h3><div class="adv-choices">${(huddleStep===0?['Ask everyone to help and assume the tasks will be covered.','Assign and confirm a named owner for each next action.']:huddleStep===1?['Continue with the original plan because everyone has already been briefed.','Regroup around the changed room, materials, and invitation.']:['Discuss what helped, what failed, and one specific adjustment.','Record that the session finished and close the discussion.']).map((t,i)=>`<button data-action="engine-72" data-engine-72="${esc(JSON.stringify([i]))}">${t}</button>`).join('')}</div><div id="huddleFeedback" aria-live="polite"></div>`,'huddle');}
function answerHuddle(i){const good=huddleStep===2?0:1;const note=i===good?'A shared plan makes ownership, changed conditions, or the next learning step explicit.':'Notice what is still assumed: who acts, what changed, or what the team learned.';huddleHistory.push({label:['Brief','Huddle','Debrief'][huddleStep]+' · '+(i===good?'Shared plan made explicit':'Assumption explored'),note});$('#huddleFeedback').innerHTML=`<div class="feedback ${i===good?'good':''}"><strong>${i===good?'A useful direction.':'A gap to discuss.'}</strong>${note}</div><button class="btn secondary" data-action="engine-73" data-engine-73="[]">Save & review my learning</button>`;}
function advDebrief(title,history,id){advStop();if(!history.length){toast('Explore at least one choice first.');return}logStudio('adv-'+id,title,history.map((x,i)=>(i+1)+'. '+x.label+' — '+x.note).join('\n'));advFrame('A useful pattern to take forward.','Educational activity, not verified professional performance.',`<h3>${title}</h3>${history.map(x=>`<div class="journey-card"><h4>${esc(x.label)}</h4><p>${esc(x.note)}</p></div>`).join('')}<div class="tool-controls"><button class="btn secondary" data-action="engine-74" data-engine-74="${esc(JSON.stringify([id]))}">Draft my own example</button><button class="btn" data-action="engine-75" data-engine-75="${esc(JSON.stringify([id==='huddle'?'improvement':'speakup']))}">Plan one action →</button></div>`,id==='cus'?'team':'huddle');}
function answerCus(i){if(cusSelected!==null||i<0||i>2)return;advStop();cusSelected=i;cusHistory.push({label:cusScenes[cusStep].options[i],note:cusScenes[cusStep].why[i]});renderCus();}
function nextCus(){advStop();if(cusStep<2){cusStep++;cusSelected=null;renderCus();return}advDebrief('CUS speaking-up practice',cusHistory,'cus');}
function resetFlow(){advStop();simStep=0;simServed=0;simQueue=0;simRework=0;simHistory=[];}
function renderFlow(){advFrame('Test a change. Watch the flow.','A deterministic fictional process simulation',`<p>A team prepares learning packs. Explore what happens when arrivals exceed processing capacity, then compare two small tests.</p><div class="adv-model"><b>Transparent model:</b> four items arrive each step; up to the selected capacity are processed. On every third step, one processed item returns for rework. Completed = processed minus returned. No randomness, clinical prediction, staffing recommendation, or external benchmark.</div><div class="adv-control-row"><label for="flowCapacity">Processing capacity per step</label><input id="flowCapacity" type="range" min="2" max="6" step="1" value="${simCapacity}" data-oninput="engine-76" data-engine-76="[]"><b id="flowCapacityValue">${simCapacity}</b></div><p class="field-hint">Changing capacity restarts the run so results remain comparable.</p><div class="adv-scene" id="advScene"><div id="flowNumbers" role="status" aria-live="polite">${flowSummary()}</div></div>${advPlayback()}<div class="adv-control-row"><button class="btn secondary" data-action="engine-77" data-engine-77="[]">Compare capacity 3 vs 5</button><button class="btn secondary" data-action="engine-78" data-engine-78="[]">Plan a PDSA test</button></div><div id="flowComparison"></div><details><summary style="min-height:44px;cursor:pointer">How to interpret this exercise</summary><p>Within this model, a persistent arrival–completion gap increases the queue. Changing capacity changes this result, but real systems have variation, constraints, costs, and interactions this model does not represent. Test a real change only through an approved process with appropriate measures.</p></details><button class="text-link" data-action="engine-79" data-engine-79="[]">Save this learning activity →</button>`,'qi');}
function setFlowCapacity(n){if(!Number.isInteger(n)||n<2||n>6)return;simCapacity=n;resetFlow();$('#flowCapacityValue').textContent=n;$('#flowNumbers').innerHTML=flowSummary();}
function compareFlow(){const a=computeFlow(3),b=computeFlow(5);$('#flowComparison').innerHTML=`<h3>Same arrivals. Same rework rule. Different capacity.</h3><table class="adv-template"><caption style="text-align:left;margin:10px 0">Synthetic results after 12 steps; 48 items arrived.</caption><thead><tr><th>Capacity</th><th>Completed</th><th>Waiting</th><th>Rework returns</th></tr></thead><tbody><tr><td>3 per step</td><td>${a.c}</td><td>${a.q}</td><td>${a.r}</td></tr><tr><td>5 per step</td><td>${b.c}</td><td>${b.q}</td><td>${b.r}</td></tr></tbody></table><p class="field-hint">These are model outputs, not evidence of real-world improvement. Completed + waiting = 48 in each run.</p>`;}
function computeFlow(capacity){let q=0,c=0,r=0;for(let i=1;i<=12;i++){q+=4;const p=Math.min(capacity,q);q-=p;const back=i%3===0&&p>0?1:0;q+=back;c+=p-back;r+=back;}return {q,c,r};}
function legacyOpenTool(id){if(id==='sbar'){showModal('The SBAR conversation guide','A fictional practice template · Not a clinical record',`<div class="notice">Practice with invented details only. Nothing typed here is sent or saved. Do not delay urgent escalation to complete a template.</div>${[['Situation','What is happening now, and how urgent is it?'],['Background','What relevant context does the recipient need?'],['Assessment','What have you observed, and what concerns you?'],['Recommendation','What action or review do you need, by when, and from whom?']].map(([title,p],i)=>`<div class="form-group"><label for="sbar${i}">${'SBAR'[i]} — ${title}</label><textarea id="sbar${i}" placeholder="${p}" style="min-height:72px" maxlength="1500"></textarea></div>`).join('')}<div class="takeaway"><p>Close the loop: confirm the recipient’s understanding, the agreed action, ownership, and the escalation plan.</p></div><div class="modal-actions"><button class="btn" data-action="engine-80" data-engine-80="[]">Download practice draft ↓</button></div>${refsHtml({refs:['team']})}`)}
if(id==='teach')showModal('Teach-back, made simple','A check of your explanation—not a test of the patient.',`<div class="learning-step"><span class="step-num">1</span><div><strong>Explain one small piece.</strong><p>Use plain language. Prioritize what matters now and offer appropriate communication support.</p></div></div><div class="learning-step"><span class="step-num">2</span><div><strong>Invite their words.</strong><p>“I want to make sure I explained that clearly. Can you tell me how you will follow the plan?”</p></div></div><div class="learning-step"><span class="step-num">3</span><div><strong>Clarify, then check again.</strong><p>Thank them. Re-explain any unclear part in a different way and invite another explanation.</p></div></div><h3>Before you finish</h3>${checklist(['The person can explain the next step in their own words.','Questions and practical barriers have been explored.','Follow-up and locally appropriate safety-net advice are clear.'])}${refsHtml({refs:['share']})}`);
if(id==='pause')showModal('A moment to reset','An optional one-minute pause.',`<p>Only begin when you are safely away from active care duties. Let your shoulders soften. Breathe comfortably; you do not need to change your breathing to use this pause.</p><div class="breath-circle" id="breathCircle"><span id="breathLabel">Ready when you are</span></div><p style="text-align:center" id="breathTime">60 seconds · No need to get it right</p><div class="modal-actions" style="justify-content:center"><button class="btn" id="breathStart" data-action="engine-81" data-engine-81="[]">Begin a quiet minute</button><button class="btn secondary" data-action="engine-28" data-engine-28="[]">Not now</button></div><p style="font-size:var(--t-12);margin-top:20px">If following the animation feels uncomfortable, return to your natural breath or stop. This is not treatment, and it does not replace rest, support, or safer working conditions.</p>`);
if(id==='safety')showModal('Before you act','A reflection prompt. Always use your organization’s required checks.',`<p>Use this as a learning aid, not as a complete clinical checklist.</p>${checklist(['Am I working within my role, training, and authorization?','Have I used the required identifiers and confirmed the intended task?','Have I checked relevant allergies, risks, and the current approved plan?','Are hand hygiene, PPE, and equipment preparation appropriate?','Does the person understand what is proposed, and has the required consent process been followed?','Is anything unclear—and have I paused to clarify it?','Do I know how to get help or escalate a concern?'])}<div class="takeaway"><p>Stop and clarify uncertainty. In emergencies, activate your local response immediately and act within your training.</p></div>${refsHtml({refs:['med','ipc']})}`);
if(id==='reflect')showModal('A note to your future self','One insight. One small action.',`<p>What happened in your learning? What did you notice about your own response? What will you try differently?</p><div class="form-group"><label for="reflection">My practice reflection</label><textarea id="reflection" maxlength="3000" placeholder="I noticed… Next time, I will…">${esc(state.reflections.general||'')}</textarea><small>Do not include patient, colleague, or confidential information. Stored only in this browser.</small></div><div class="modal-actions"><button class="btn" data-action="engine-82" data-engine-82="[]">Save my reflection ✓</button></div>`);
if(id==='evidence')showModal('A critical appraisal pause','Questions to ask before applying a claim.',`${checklist(['Is the source authentic, and have I read beyond the headline or generated summary?','What question was asked, and is the study design appropriate for it?','How large and clinically meaningful is the effect, including absolute benefits and harms?','How uncertain are the results, and what limitations or conflicts matter?','Does the population and setting resemble the person and context in front of me?','Is this consistent with current authoritative guidance and local policy?','Have I involved the appropriate clinician and considered the patient’s preferences?'])}<div class="takeaway"><p>A single study—or a polished AI answer—is not a complete basis for a clinical decision.</p></div><p style="font-size:var(--t-12)">Editorial critical-appraisal prompts, not a validated scoring tool.</p>${refsHtml({refs:['ai','share']})}`)}
function refsHtml(l){return `<div class="source-list"><b>${l.editorial?'Editorial learning synthesis · supporting resources':'Supporting resources'}</b>${l.refs.map(r=>`<div>${sources[r].name} <a href="${sources[r].url}" target="_blank" rel="noopener noreferrer">Open source ↗</a></div>`).join('')}${!l.refs.length?'<div>General wellbeing reflection; not a therapeutic intervention or clinical guideline.</div>':''}<div>Source links selected 14 October 2026. Check live sources and local policy for updates. These resources do not endorse Carecraft.</div></div>`}
function saveReflection(id){state.reflections[id]=$('#reflection').value;persist();toast('Reflection saved in this browser.');if(currentPage==='progress')render()}
function checklist(items){return `<ul class="checklist">${items.map(x=>`<li><label><input type="checkbox"> <span>${x}</span></label></li>`).join('')}</ul>`}
function startBreathing(){clearInterval(breathTimer);let remaining=60;$('#breathCircle').classList.add('running');$('#breathLabel').textContent='Just be here';$('#breathStart').disabled=true;$('#breathStart').textContent='Your quiet minute';$('#breathTime').textContent='60 seconds remaining';breathTimer=setInterval(()=>{remaining--;if(!$('#breathTime')){clearInterval(breathTimer);return}$('#breathTime').textContent=remaining+' seconds remaining';$('#breathLabel').textContent=remaining>40?'Relax your shoulders':remaining>20?'Breathe comfortably':'Make a little space';if(remaining<=0){clearInterval(breathTimer);$('#breathCircle').classList.remove('running');$('#breathLabel').textContent='A fresh start';$('#breathTime').textContent='Your quiet minute is complete.';$('#breathStart').disabled=false;$('#breathStart').textContent='Take another minute'}} ,1000)}
function downloadSBAR(){let text='CARECRAFT — FICTIONAL SBAR PRACTICE DRAFT\nNot a clinical record.\n\n';['Situation','Background','Assessment','Recommendation'].forEach((s,i)=>text+=s.toUpperCase()+'\n'+$('#sbar'+i).value+'\n\n');downloadFile(text,'carecraft-sbar-practice.txt');toast('Practice draft downloaded.')}
function openEvidenceWorkspace(){const sample='FICTIONAL AI OUTPUT: “A recent study proves this method works for every patient. It reduces risk by 50%, so all services should adopt it immediately. Reference: Example Journal, 2026.”';const flags=['The source is vague and has not been independently located.','“Every patient” overgeneralizes beyond a defined population.','Relative benefit is given without absolute risks or a time frame.','Immediate adoption is proposed without appraisal or local review.'];showModal('Check the claim, then the evidence.','Fictional AI output-checking exercise',`<div class="notice">The quotation below is deliberately invented for learning. It contains no usable clinical recommendation or real citation.</div><div class="scenario-event">${sample}</div><h3>Which details need checking?</h3><div id="evidenceFlags">${flags.map((f,i)=>`<label class="appraisal-flag"><input type="checkbox" id="evidenceFlag${i}"><span>${f}</span></label>`).join('')}</div><button class="btn secondary" data-action="engine-83" data-engine-83="[]">Explore the reasoning</button><div id="evidenceFlagFeedback" aria-live="polite"></div><div class="form-group" style="margin-top:22px"><label for="appraisalNote">My independent verification plan</label><textarea id="appraisalNote" maxlength="2000" data-oninput="engine-84" data-engine-84="[]" placeholder="Which actual source will I locate? What claim will I check? Who needs to review it?">${esc(state.toolDrafts.evidence?.[0]||'')}</textarea><small>Saved locally. Keep confidential material out.</small></div><div class="tool-controls"><button class="btn secondary" data-action="engine-85" data-engine-85="[]">Download my plan ↓</button><button class="btn" data-action="engine-86" data-engine-86="[]">Plan an action →</button></div><div class="source-context">Informed by WHO guidance on AI governance and human oversight. This original exercise is not a validated appraisal instrument.</div>`);}
function checkEvidenceFlags(){const count=[0,1,2,3].filter(i=>$('#evidenceFlag'+i).checked).length;$('#evidenceFlagFeedback').innerHTML=`<div class="feedback good"><strong>${count} of 4 checking points selected.</strong>All four need attention. Locate the real source, compare the actual population and outcome, examine absolute benefit and uncertainty, and use the approved review process before applying a claim. Selecting flags does not verify a clinical claim.</div>`;}
function workspacePreview(id,values){if(id==='fishbone')return `<div class="adv-preview-bone"><h4>Effect: ${esc(values[0]||'Define the process problem')}</h4>${workspaceSpecs[id].fields.slice(1).map((f,i)=>`<div><b>${esc(f.split(' — ')[0])}</b><p>${esc(values[i+1]||'Possible contributors or evidence to investigate.')}</p></div>`).join('')}<p class="field-hint">Possible causes are hypotheses to investigate, not proven root causes.</p></div>`;return expansionBasePreview(id,values);}
function expansionBasePreview(id,values){return workspaceSpecs[id].fields.map((f,i)=>`<b>${esc(f.split(' — ')[0])}</b><p>${esc(values[i]||'Your words will appear here.')}</p>`).join('');}
function toolValues(id){return state.toolDrafts[id]||workspaceSpecs[id].fields.map(()=>'');}
function drawCauseCanvas(){const canvas=$('#causeCanvas');if(!canvas)return;const rect=canvas.getBoundingClientRect();if(!rect.width)return;const ratio=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.width*.48*ratio);const c=canvas.getContext('2d');c.setTransform(canvas.width/1000,0,0,canvas.height/480,0,0);const dark=document.body.classList.contains('theme-dark'),ink=dark?'#e7efe9':'#20332f',muted=dark?'#b9c9be':'#596b64',bg=dark?'#23382e':'#f4f7f1';c.fillStyle=bg;c.fillRect(0,0,1000,480);const vals=toolValues('fishbone');cLine(c,45,235,775,235,muted,3);cRound(c,780,170,205,130,15,dark?'#34513f':'#e0eee3');function words(t,x,y,max=24,lines=3){const tokens=t.split(/\s+/);let line='',row=0;c.fillStyle=ink;c.font='15px "Inter",sans-serif';for(const token of tokens){if((line+' '+token).length>max){c.fillText(line,x,y+row*20);row++;line=token;if(row>=lines)break}else line+=(line?' ':'')+token;}if(row<lines)c.fillText(line,x,y+row*20);}
words(vals[0]||'Define the process effect',795,203,21,4);const cats=['People & teamwork','Process & policy','Equipment & materials','Environment & workload','Measurement'];cats.forEach((label,i)=>{const x=100+i*137,up=i%2===0,endY=up?75:405;cLine(c,x+75,235,x,endY,muted,2);c.fillStyle=ink;c.font='bold 16px "Inter",sans-serif';c.fillText(label,x-45,up?48:432);words(vals[i+1]||'Possible contributors to investigate',x-45,up?85:310,21,3)});c.fillStyle=muted;c.font='13px "Inter",sans-serif';c.fillText('Possible causes are hypotheses. Investigate before drawing conclusions.',35,465);}
function downloadWorkspace(id){const spec=workspaceSpecs[id];updateWorkspace(id);downloadFile('CARECRAFT — FICTIONAL PRACTICE DRAFT\n'+spec.title+'\nNot a clinical record or verified assessment.\n\n'+spec.fields.map((f,i)=>f+'\n'+state.toolDrafts[id][i]).join('\n\n'),'carecraft-'+id+'-practice.txt');}
function saveAction(lesson,silent=false){const el=$('#actionText');if(!el||!el.value.trim()){if(!silent)toast('Write one action before saving.');return false}let due=$('#actionDue').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(due)){toast('Choose a review date.');return false}let existing=state.actions.find(a=>a.lesson===lesson&&a.status==='planned');if(existing){existing.text=el.value.trim();existing.due=due;}else state.actions.push({id:'action-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),lesson,text:el.value.trim(),due,status:'planned',created:new Date().toISOString(),review:''});delete state.toolDrafts['action-'+lesson];persistQuiet();if(!silent)toast('Action saved. Review it in My Growth.');return true;}
function ccLearningBrief(l){const u=ccUsage(l.id);return `<section class="cc-learning-brief" aria-label="Where this learning helps"><div class="cc-brief-grid"><div>${hcaIcon('team')}<span><strong>Who it helps</strong><p>${esc(u.who)}</p></span></div><div>${hcaIcon('calendar')}<span><strong>Use it when</strong><p>${esc(u.when)}</p></span></div></div><div class="cc-brief-action">${hcaIcon('route')}<span><strong>One action to practise</strong><p>${esc(u.action)}</p></span></div></section>`;}
function ccEvidenceHTML(id){const e=CC_EVIDENCE[id]||CC_EVIDENCE.harm;return `<section class="cc-evidence" aria-label="Related evidence: ${esc(e.title)}"><div class="cc-evidence-head">Related evidence</div><h4 class="cc-evidence-title">${esc(e.title)}</h4><span class="cc-study-type">${esc(e.type)}</span><p class="cc-finding">${esc(e.finding)}</p><div class="cc-evidence-pair">${e.numbers.map(([n,t])=>`<div><strong class="cc-evidence-number">${n}</strong><span class="cc-evidence-unit">${t}</span></div>`).join('')}</div>${e.kind==='bar'?`<div class="cc-evidence-bar" aria-hidden="true"><span style="width:${e.ratio}%"></span></div>`:e.kind==='compare'?`<div class="cc-comparison-bars" aria-hidden="true"><i></i><i style="width:${e.ratio}%"></i></div>`:''}<p class="cc-evidence-context">${esc(e.context)}</p><details class="cc-study-details"><summary>Who and what was studied?</summary><p>${esc(e.population)}</p></details><a href="${e.url}" target="_blank" rel="noopener noreferrer">${esc(e.source)} ↗</a></section>`;}
function ccTopicArtwork(id,category='skills'){
 const dark=ccIsDark(),palette=dark?{knowledge:['#132d43','#b6cde3'],skills:['#103d42','#8ed8cf'],attitudes:['#392d2a','#efbc97']}:{knowledge:['#e5edf4','#10253A'],skills:['#e4f1ed','#087D7A'],attitudes:['#f3e8dd','#92522D']};
 const [bg,ink]=palette[category]||palette.skills;
 const aliases={handover:'sbar',teachback:'teachback-skill','ai-case':'ai','med-case':'med-transitions',hygiene:'infection','sbar-studio':'sbar',cus:'speakup',huddle:'inclusive-leadership','cc-teach':'teachback-skill','cc-risk':'risk-evidence','cc-reconcile':'med-transitions','cc-bias':'reasoning','cc-verify':'ai','cc-access':'equity','cc-interrupt':'interruptions','cc-compassion':'compassion-boundaries','sim-handover':'sbar','sim-interruptions':'interruptions','sim-shared-choice':'shared'};
 const key=aliases[id]||id,path=CC_ART_ICONS[key]||CC_ART_ICONS.improvement,seed=Array.from(id).reduce((n,c)=>n+c.charCodeAt(0),0);
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="400" viewBox="0 0 800 400"><title>${esc('Topic artwork: '+id)}</title><rect width="800" height="400" fill="${bg}"/><circle cx="${660+seed%80}" cy="${40+seed%70}" r="180" fill="${ink}" opacity=".045"/><circle cx="${60+seed%100}" cy="360" r="140" fill="${ink}" opacity=".055"/><path d="M60 200h160m360 0h160" stroke="${ink}" stroke-width="2" opacity=".16"/><circle cx="400" cy="200" r="112" fill="${ink}" opacity=".055"/><g transform="translate(340 140) scale(5)" fill="none" stroke="${ink}" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round">${path}</g><circle cx="${196+seed%30}" cy="${100+seed%50}" r="6" fill="${ink}" opacity=".3"/><circle cx="${570+seed%40}" cy="${270+seed%40}" r="4" fill="${ink}" opacity=".4"/></svg>`;
 return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
}
function ccHeroArtwork(){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 600"><rect width="900" height="600" fill="#10253A"/><circle cx="720" cy="270" r="280" fill="#087D7A" opacity=".4"/><circle cx="730" cy="260" r="200" fill="none" stroke="#C9A24A" stroke-width="2" opacity=".35"/><circle cx="730" cy="260" r="155" fill="none" stroke="#FFFDF9" stroke-width="2" opacity=".14"/><path d="M520 200h70v70h70v70h-70v70h-70v-70h-70v-70h70z" fill="#FFFDF9" opacity=".12"/><path d="M360 580Q630 420 930 510" fill="none" stroke="#BD764A" stroke-width="50" opacity=".25"/></svg>');}
function startAssessment(){assessmentIndex=0;assessmentAnswers=[];renderAssessment()}
function renderAssessment(){if(assessmentIndex===3){let min=Math.min(...assessmentAnswers),focus=assessmentQuestions[assessmentAnswers.indexOf(min)][0];state.assessment={focus,answers:assessmentAnswers,date:new Date().toISOString().slice(0,10)};persist();showModal('A useful place to start.','Your self-reflection, not a competency assessment.',`<div class="takeaway"><div class="eyebrow">YOUR SUGGESTED FOCUS</div><h2 style="text-transform:capitalize">${focus}</h2><p style="margin-top:9px">${{knowledge:'Strengthen your foundations in safety, clinical reasoning, and digital literacy.',skills:'Build practical habits for communication, handovers, and shared decisions.',attitudes:'Make space for empathy, cultural humility, speaking up, and sustainable practice.'}[focus]}</p></div><p>This suggestion uses your lowest confidence rating. If ratings are equal, it starts with the first dimension. It is only a starting point; you know your needs and role best.</p><div class="modal-actions"><button class="btn secondary" data-action="engine-87" data-engine-87="[]">Reflect again</button><button class="btn" data-action="engine-88" data-engine-88="${esc(JSON.stringify([focus]))}">Explore my focus ↗</button></div>`);if(currentPage==='dashboard'||currentPage==='pathways')render();return}let [cat,q]=assessmentQuestions[assessmentIndex];showModal('Your practice. Your next step.',`Reflection ${assessmentIndex+1} of 3 · About 2 minutes`,`<div class="progress-track"><div style="width:${assessmentIndex/3*100}%"></div></div><span class="pill ${cat}" style="margin-top:15px">${cat}</span><p class="question" style="margin-top:18px">${q}</p><p>Think about your recent experience. There are no right or wrong answers.</p><div class="assessment-options">${[['○','Building confidence','I would value support'],['◐','Finding my rhythm','I am growing'],['●','Feeling confident','I want to refine']].map(([icon,title,sub],i)=>`<button data-action="engine-89" data-engine-89="${esc(JSON.stringify([i]))}"><span class="ico">${icon}</span><b>${title}</b><small>${sub}</small></button>`).join('')}</div><small class="muted">This self-check is not a validated clinical assessment.</small>${assessmentIndex?'<div class="modal-actions"><button class="text-link" data-action="engine-90" data-engine-90="[]">← Previous reflection</button></div>':''}`)}
function updateStudioLog(){let el=$('#studioLog');if(el)el.innerHTML=studioLogHtml();document.querySelectorAll('.studio-tab-check').forEach(el=>{let tab=el.dataset.tab;el.textContent=studioLogged(tab)||(tab==='movement'&&studioRecords().some(r=>r.id.startsWith('movement-')))?'✓':''})}
function studioLogged(id){return studioRecords().some(r=>r.id===id)}
function showBranchDebrief(r,b){showModal('A decision trail. A next useful step.','Learning choices, not a competency score.',`<div class="takeaway"><p>${b.debrief}</p></div>${r.path.map((p,i)=>`<div class="journey-card"><div class="eyebrow muted">DECISION ${i+1}</div><h4>${esc(p.label)}</h4><p>${esc(p.feedback)}</p></div>`).join('')}<div class="modal-actions"><button class="btn secondary" data-action="engine-28" data-engine-28="[]">Back to practice</button><button class="btn" data-action="engine-91" data-engine-91="${esc(JSON.stringify([b.lesson]))}">Plan one action →</button></div>`);}